// The startup update check: the newest better-tasks release (a vX.Y.Z tag of its repo) against the one this
// project pins and the one installed. Newer: asked once per version; Yes moves the pin, updates the plugin,
// then asks the user to restart Claude Code (I'll restart / Skip). Only for an install from the marketplace
// (a linked install is the user's own).

export const PLUGIN_ID = 'better-tasks@better-tasks'
export const MARKETPLACE_NAME = 'better-tasks'
export const UPDATE_YES = 'Yes'
export const UPDATE_NO = 'No'
export const UPDATE_HEADER = 'Update'
/** The store key holding the release the user said No to: not asked again for it. */
export const DECLINED_KEY = 'updateDeclined'

export const updateQuestion = (tag: string) => `better-tasks ${tag} is out. Update?`
export const updatedLine = (tag: string) => `better-tasks: updated to ${tag}.`

/** After the update, the restart is a question: the user restarts on their own, or skips it. */
export const RESTART_LATER = "I'll restart"
export const RESTART_SKIP = 'Skip'
export const RESTART_HEADER = 'Restart'
export const restartQuestion = (tag: string) => `better-tasks ${tag} is installed. Restart Claude Code to use it: quit, then run claude --continue.`
export const restartLaterLine = (tag: string) => `better-tasks: ${tag} runs once you restart Claude Code.`

/** An install Claude Code knows: its version and the scope `claude plugin update` needs. */
export type Install = { version: string; scope: string }

const TAG = /^v(\d+)\.(\d+)\.(\d+)$/

/** True for a release tag: vX.Y.Z. */
export const isReleaseTag = (ref: unknown): ref is string => typeof ref === 'string' && TAG.test(ref)

// Values from a project's shared settings reach git and claude as arguments; a cloned repo writes that file.
// Only these shapes pass, so none can read as an option (--upload-pack=…) or a transport (ext::…).
const GITHUB_REPO = /^[A-Za-z0-9][A-Za-z0-9-]*\/[A-Za-z0-9_.][A-Za-z0-9_.-]*$/
const HTTPS_URL = /^https:\/\/[A-Za-z0-9][A-Za-z0-9.-]*(:\d+)?\/[^\s#]*$/
const SCOPES = ['user', 'project', 'local', 'managed']

/** True for a GitHub `owner/repo`. */
export const isGithubRepo = (repo: unknown): repo is string => typeof repo === 'string' && GITHUB_REPO.test(repo)
/** True for a plain https:// git URL: no spaces, no fragment, nothing an option or another transport could hide in. */
export const isHttpsUrl = (url: unknown): url is string => typeof url === 'string' && HTTPS_URL.test(url)
/** True for a marketplace source `claude plugin marketplace add` may get: owner/repo or a plain https URL. */
export const isSafeSource = (source: string) => isGithubRepo(source) || isHttpsUrl(source)

/** The release tags in `git ls-remote --tags --refs` output. */
export function releaseTags(lsRemote: string): string[] {
  return lsRemote.split('\n').map(line => line.split('refs/tags/')[1]?.trim() ?? '').filter(isReleaseTag)
}

/** True when tag `a` is a later release than `b`. */
export function isNewer(a: string, b: string): boolean {
  const [x, y] = [numbers(a), numbers(b)]
  const differing = x.findIndex((part, i) => part !== y[i])
  return differing !== -1 && (x[differing] ?? 0) > (y[differing] ?? 0)
}

export function newestTag(tags: string[]): string | undefined {
  return tags.reduce<string | undefined>((best, tag) => (best === undefined || isNewer(tag, best) ? tag : best), undefined)
}

/**
 * The install this session runs, from `claude plugin list --json`: the entry at the plugin's own folder,
 * this project's when both scopes share it. Undefined for a linked install or output that isn't the list.
 */
export function activeInstall(listJson: string, pluginRoot: string, projectRoot: string): Install | undefined {
  const entries = parseList(listJson).filter(entry => entry.id === PLUGIN_ID && trimSlash(entry.installPath) === trimSlash(pluginRoot))
  const entry = entries.find(each => each.scope !== 'user' && each.projectPath === projectRoot) ?? entries.find(each => each.scope === 'user')
  return entry && typeof entry.version === 'string' && isReleaseTag(`v${entry.version}`) ? { version: entry.version, scope: SCOPES.includes(entry.scope ?? 'user') ? (entry.scope ?? 'user') : 'user' } : undefined
}

/**
 * The version installed at `scope` (this project's entry, for project or local), from `claude plugin list --json`.
 * After an update the entry lives in the new release's folder, so it is found by scope, not by the plugin's folder.
 */
export function versionAt(listJson: string, scope: string, projectRoot: string): string | undefined {
  const entry = parseList(listJson).find(each => each.id === PLUGIN_ID && (each.scope ?? 'user') === scope && (scope === 'user' || each.projectPath === projectRoot))
  return typeof entry?.version === 'string' ? entry.version : undefined
}

/**
 * The release to offer, or undefined when there is nothing to ask: none newer than both the installed
 * release and the project's pin, or the user already said No to it.
 */
export function offeredRelease(tags: string[], installed: string, pinned: string | undefined, declined: unknown): string | undefined {
  const newest = newestTag(tags)
  if (newest === undefined || newest === declined) return undefined
  const behind = isNewer(newest, `v${installed}`) || (pinned !== undefined && isNewer(newest, pinned))
  return behind ? newest : undefined
}

/**
 * The release to pin a project to now: the one installed when its repo has that tag (or the repo can't be
 * reached), else the repo's newest. Undefined for a linked install offline.
 */
export function pinTarget(tags: string[], installed: string | undefined): string | undefined {
  const current = installed === undefined ? undefined : `v${installed}`
  if (current !== undefined && (tags.length === 0 || tags.includes(current))) return current
  return newestTag(tags)
}

export const lsRemoteArgv = (url: string) => ['git', 'ls-remote', '--tags', '--refs', '--', url]
export const listArgv = ['claude', 'plugin', 'list', '--json']
/**
 * Moves the marketplace pinned in the project's (or the user's) settings to `tag`: those settings and Claude Code's
 * copy of the marketplace. Undefined for a source or tag of another shape.
 */
export function repinArgv(source: string, tag: string, scope: 'project' | 'user' = 'project'): string[] | undefined {
  if (!isSafeSource(source) || !isReleaseTag(tag)) return undefined
  return ['claude', 'plugin', 'marketplace', 'add', '--scope', scope, '--', `${source}#${tag}`]
}
export const refreshArgv = ['claude', 'plugin', 'marketplace', 'update', MARKETPLACE_NAME]

/** Managed settings, per OS; a file that isn't there is skipped. */
export const MANAGED_SETTINGS = ['/Library/Application Support/ClaudeCode/managed-settings.json', '/etc/claude-code/managed-settings.json']

/**
 * True when user or managed settings declare the better-tasks marketplace (extraKnownMarketplaces). Claude Code
 * then takes its source from there alone and refuses `marketplace add` from any other, a project's pin included.
 */
export function declaresMarketplace(settingsText: string | undefined): boolean {
  return declarationOf(settingsText) !== undefined
}

/**
 * The release tag the user's settings pin better-tasks to; undefined when they pin none. `claude plugin marketplace
 * add owner/repo#tag` writes such a pin, and then only an add from that same source#tag is let through.
 */
export function declaredTag(settingsText: string | undefined): string | undefined {
  const ref = declarationOf(settingsText)?.source?.ref
  return isReleaseTag(ref) ? ref : undefined
}

/** The user's settings with their better-tasks pin moved to `tag`, the rest kept; undefined when they pin no release. */
export function withDeclaredTag(settingsText: string | undefined, tag: string): string | undefined {
  if (declaredTag(settingsText) === undefined || !isReleaseTag(tag)) return undefined
  const settings = JSON.parse(settingsText ?? '{}')
  settings.extraKnownMarketplaces[MARKETPLACE_NAME].source.ref = tag
  return `${JSON.stringify(settings, null, 2)}\n`
}

type Declaration = { source?: { ref?: unknown } }

function declarationOf(settingsText: string | undefined): Declaration | undefined {
  try {
    const declared = JSON.parse(settingsText ?? '{}')?.extraKnownMarketplaces
    const isObject = typeof declared === 'object' && declared !== null
    return isObject && Object.hasOwn(declared, MARKETPLACE_NAME) ? (declared[MARKETPLACE_NAME] ?? {}) : undefined
  } catch {
    return undefined
  }
}
export const updateArgv = (scope: string) => ['claude', 'plugin', 'update', '--scope', SCOPES.includes(scope) ? scope : 'user', '--', PLUGIN_ID]

type ListEntry = { id?: unknown; version?: unknown; scope?: string; installPath?: unknown; projectPath?: unknown }

function parseList(text: string): ListEntry[] {
  try {
    const json: unknown = JSON.parse(text)
    return Array.isArray(json) ? (json as ListEntry[]) : []
  } catch {
    return []
  }
}

const numbers = (tag: string) => (TAG.exec(tag) ?? []).slice(1).map(Number)
const trimSlash = (path: unknown) => (typeof path === 'string' ? path.replace(/\/+$/, '') : '')

files.hooks/intellij.ts:
// Keeps JetBrains IDEs (IntelliJ, WebStorm, PyCharm...) from indexing teammate worktrees.
// Claude Code puts each worktree, a full copy of the repo, in <project>/.claude/worktrees/, so the IDE
// sees it as project content and re-indexes a whole copy each time one is made, merged or removed.
// Done by default, not asked (project setting excludeWorktreesFromIde, on unless set false): with worktrees on and a
// .idea folder, each session start marks that folder as excluded in the .idea module file.

export const WORKTREES_DIR = '.claude/worktrees'

export const IDE_SETTING = 'excludeWorktreesFromIde'

const EXCLUDE_LINE = `<excludeFolder url="file://$MODULE_DIR$/${WORKTREES_DIR}" />`

export type IdeFiles = {
  root: () => Promise<string>
  read: (path: string) => Promise<string>
  write: (path: string, text: string) => Promise<void>
}

/** The module files .idea/modules.xml lists, as absolute paths. */
export function modulePaths(modulesXml: string, root: string): string[] {
  const paths = [...modulesXml.matchAll(/filepath="([^"]+)"/g)].map(match => match[1]!)
  return paths.map(path => path.replaceAll('$PROJECT_DIR$', root))
}

/** Where `$MODULE_DIR$` points for a module file: its folder, or the project for one inside .idea/. */
export function moduleDir(imlPath: string): string {
  const dir = imlPath.slice(0, imlPath.lastIndexOf('/'))
  return dir.endsWith('/.idea') ? dir.slice(0, -'/.idea'.length) : dir
}

/**
 * The module file with the worktrees folder excluded under its content root, when that root is
 * the project itself; undefined when there is nothing to change.
 */
export function withWorktreesExcluded(iml: string, isProjectModule: boolean): string | undefined {
  if (!isProjectModule || iml.includes(`$MODULE_DIR$/${WORKTREES_DIR}"`)) return undefined
  const open = /(<content url="file:\/\/\$MODULE_DIR\$")\s*>\n?/
  const closed = /(<content url="file:\/\/\$MODULE_DIR\$")\s*\/>/
  const indent = (iml.match(/^([ \t]*)<content url="file:\/\/\$MODULE_DIR\$"/m)?.[1] ?? '    ') + '  '
  if (open.test(iml)) return iml.replace(open, (_, start: string) => `${start}>\n${indent}${EXCLUDE_LINE}\n`)
  if (closed.test(iml)) return iml.replace(closed, (_, start: string) => `${start}>\n${indent}${EXCLUDE_LINE}\n${indent.slice(2)}</content>`)
  return undefined
}

/** The module file IntelliJ IDEA itself writes for a plain folder, with the worktrees excluded. */
export function folderModule(): string {
  return `<?xml version="1.0" encoding="UTF-8"?>
<module type="JAVA_MODULE" version="4">
  <component name="NewModuleRootManager" inherit-compiler-output="true">
    <exclude-output />
    <content url="file://$MODULE_DIR$">
      ${EXCLUDE_LINE}
    </content>
    <orderEntry type="inheritedJdk" />
    <orderEntry type="sourceFolder" forTests="false" />
  </component>
</module>
`
}

export function modulesXml(imlName: string): string {
  return `<?xml version="1.0" encoding="UTF-8"?>
<project version="4">
  <component name="ProjectModuleManager">
    <modules>
      <module fileurl="file://$PROJECT_DIR$/.idea/${imlName}" filepath="$PROJECT_DIR$/.idea/${imlName}" />
    </modules>
  </component>
</project>
`
}

/**
 * A project whose modules come from a build tool (Gradle, Maven, sbt...) keeps them out of .idea;
 * writing a module file there would add a second one, so such projects are left alone.
 */
export function isBuildToolProject(ideaFiles: string[], miscXml: string): boolean {
  const toolFiles = ['gradle.xml', 'sbt.xml', 'bsp.xml', 'kotlinc.xml']
  const isTool = ideaFiles.some(name => toolFiles.includes(name))
  return isTool || /ExternalStorageConfigurationManager" enabled="true"|MavenProjectsManager/.test(miscXml)
}

/**
 * Marks .claude/worktrees as excluded in the project's IntelliJ module; returns the line to log when it
 * changed something. A project with no .idea/ is left as it is.
 */
export async function excludeWorktrees(files: IdeFiles, ideaFiles: string[] | undefined): Promise<string | undefined> {
  if (ideaFiles === undefined) return undefined
  const root = await files.root()
  const idea = `${root}/.idea`
  const modules = await files.read(`${idea}/modules.xml`).catch(() => undefined)
  if (modules === undefined) return excludeInNewModule(files, root, ideaFiles)
  for (const path of modulePaths(modules, root)) {
    const iml = await files.read(path).catch(() => undefined)
    const changed = iml === undefined ? undefined : withWorktreesExcluded(iml, moduleDir(path) === root)
    if (changed === undefined) continue
    await files.write(path, changed)
    return `better-tasks: IntelliJ now skips ${WORKTREES_DIR}/ (teammate worktrees), so they are not indexed`
  }
  return undefined
}

/** IntelliJ keeps a plain folder's module only in its cache until it is changed; this writes it, excluded. */
async function excludeInNewModule(files: IdeFiles, root: string, ideaFiles: string[]): Promise<string | undefined> {
  const misc = await files.read(`${root}/.idea/misc.xml`).catch(() => '')
  if (isBuildToolProject(ideaFiles, misc)) return undefined
  const imlName = `${root.slice(root.lastIndexOf('/') + 1)}.iml`
  if (ideaFiles.includes(imlName)) return undefined
  await files.write(`${root}/.idea/${imlName}`, folderModule())
  await files.write(`${root}/.idea/modules.xml`, modulesXml(imlName))
  return `better-tasks: IntelliJ now skips ${WORKTREES_DIR}/ (teammate worktrees), so they are not indexed`
}

files.hooks/migrate.ts:
import type { FsEntry } from 'claude-code'

// One-time move of a project's files from the old folder (.claude/manager/, tasks in its tasks/)
// to .claude/tasks/ (tasks, sprints.md, config.json and the overrides side by side).

export const OLD_DIR = '.claude/manager'
export const NEW_DIR = '.claude/tasks'

export type Mover = {
  root: () => Promise<string>
  list: (path: string) => Promise<FsEntry[]>
  read: (path: string) => Promise<string>
  write: (path: string, text: string) => Promise<void>
  run: (argv: string[]) => Promise<{ exitCode: number }>
}

/** Old paths in a config.json, pointed at the new folder. */
export function movedConfig(text: string): string {
  return text.replaceAll(`${OLD_DIR}/tasks`, NEW_DIR).replaceAll(OLD_DIR, NEW_DIR)
}

/** Moves the old folder when the project has it and not the new one; returns the line to log, if it moved. */
export async function migrateFolder(io: Mover): Promise<string | undefined> {
  const root = await io.root()
  const isDir = (path: string) => io.list(path).then(() => true, () => false)
  const [from, to] = [`${root}/${OLD_DIR}`, `${root}/${NEW_DIR}`]
  if (!(await isDir(from)) || (await isDir(to))) return undefined

  if ((await io.run(['mv', from, to])).exitCode !== 0) return `better-tasks: could not move ${OLD_DIR}/ to ${NEW_DIR}/`
  if (await isDir(`${to}/tasks`)) {
    for (const entry of await io.list(`${to}/tasks`)) await io.run(['mv', '-n', `${to}/tasks/${entry.name}`, `${to}/${entry.name}`])
    await io.run(['rmdir', `${to}/tasks`])
  }
  const config = await io.read(`${to}/config.json`).catch(() => undefined)
  if (config !== undefined && movedConfig(config) !== config) await io.write(`${to}/config.json`, movedConfig(config))
  return `better-tasks: moved ${OLD_DIR}/ to ${NEW_DIR}/ (tasks, sprints, settings)`
}

// One-time move of the old instruction overrides to .claude/better-tasks/ (template.ts): coordinator.md becomes
// lead.md, teammate.md stays teammate.md; the "instructions" setting (paths) becomes a "Project rules" section.

const EXTEND_MARK = '<!-- extend -->'
const RULE_MOVES = [['coordinator.md', 'lead.md'], ['teammate.md', 'teammate.md']] as const

/** An old override as a new one: the extend marker is the new default; a plain one replaced, so it says so. */
export function movedRule(old: string): string {
  const text = old.trimStart()
  return text.startsWith(EXTEND_MARK) ? text.slice(EXTEND_MARK.length).trimStart() : `---\nreplace: true\n---\n${text}`
}

/** The "instructions" setting's paths, as a section both the lead's and the teammates' rules end with. */
export function projectRulesSection(paths: string): string {
  return `\n## Project rules\nRead before you work: ${paths.split(',').map(path => path.trim()).filter(Boolean).join(', ')}.\n`
}

/** Moves the old overrides and the "instructions" setting into .claude/better-tasks/; returns the line to log, if anything moved. */
export async function migrateRules(io: Mover): Promise<string | undefined> {
  const root = await io.root()
  const read = (path: string) => io.read(`${root}/${path}`).catch(() => undefined)
  const moved: string[] = []
  for (const [from, to] of RULE_MOVES) {
    const old = await read(`${NEW_DIR}/${from}`)
    if (old === undefined) continue
    if ((await read(`${RULES_DIR}/${to}`)) === undefined) await io.write(`${root}/${RULES_DIR}/${to}`, movedRule(old))
    await io.run(['rm', `${root}/${NEW_DIR}/${from}`])
    moved.push(`${from} → ${RULES_DIR}/${to}`)
  }
  const configText = await read(`${NEW_DIR}/config.json`)
  const config = parsed(configText)
  const paths = typeof config?.instructions === 'string' ? config.instructions.trim() : ''
  if (config && 'instructions' in config) {
    for (const to of ['lead.md', 'teammate.md']) {
      if (!paths) break
      const own = (await read(`${RULES_DIR}/${to}`)) ?? ''
      await io.write(`${root}/${RULES_DIR}/${to}`, `${own.trimEnd()}\n${projectRulesSection(paths)}`.trimStart())
    }
    const { instructions: _dropped, ...rest } = config
    await io.write(`${root}/${NEW_DIR}/config.json`, `${JSON.stringify(rest, null, 2)}\n`)
    if (paths) moved.push(`the "instructions" setting → a "Project rules" section in ${RULES_DIR}/lead.md and teammate.md`)
  }
  return moved.length > 0 ? `better-tasks: moved ${moved.join('; ')}` : undefined
}

const RULES_DIR = '.claude/better-tasks'

function parsed(text: string | undefined): Record<string, unknown> | undefined {
  if (text === undefined) return undefined
  try {
    const json = JSON.parse(text) as unknown
    return json && typeof json === 'object' && !Array.isArray(json) ? (json as Record<string, unknown>) : undefined
  } catch {
    return undefined
  }
}

